output_text:
[
  {
    "id": "return_cart_to_nw_corral",
    "text": "A shopper who starts a trip is obliged to park the cart at the north-west cart return before leaving.",
    "abstraction": {
      "state_properties": {
        "nw_cart_return_cell": "at(0,1)",
        "cart_parked_at_nw_return": "cartAt(0,1)",
        "holding_cart": "hasCart"
      },
      "events": {
        "return_cart_nw": {
          "pre": {
            "and": [
              "holding_cart",
              "nw_cart_return_cell",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_nw_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_nw"
    }
  },
  {
    "id": "only_leave_cart_at_nw_corral",
    "text": "Leaving a cart is prohibited unless the shopper is at the north-west cart return.",
    "abstraction": {
      "state_properties": {
        "nw_cart_return_cell": "at(0,1)",
        "not_at_nw_cart_return": {
          "not": "nw_cart_return_cell"
        }
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart",
          "not_at_nw_cart_return"
        ]
      }
    }
  },
  {
    "id": "take_cart_from_entrance_station",
    "text": "A shopper is obliged to check out the entrance cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "holding_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "holding_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_shelf_pickup_without_cart",
    "text": "Picking up shelf items without already having a cart is prohibited.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "no_cart_in_hand": {
          "not": "holding_cart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "no_cart_in_hand"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "Carrying grocery items by hand is prohibited, so collected items should be transported in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "holding_cart": "hasCart",
        "improper_hand_carry": {
          "and": [
            "carrying_item_by_hand",
            {
              "not": "holding_cart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "Exiting the store is prohibited unless the cart is already parked at the north-west cart return.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_nw_return": "cartAt(0,1)",
        "cart_not_returned": {
          "not": "cart_parked_at_nw_return"
        }
      },
      "events": {
        "attempt_exit": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "attempt_exit",
          "cart_not_returned"
        ]
      }
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Taking a shopping cart through the exit is prohibited.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "at_exit_door": "at(9,5)"
      },
      "events": {
        "exit_while_holding_cart": {
          "pre": {
            "and": [
              "EXIT",
              "holding_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_while_holding_cart"
    }
  },
  {
    "id": "after_item_pickup_return_cart",
    "text": "After any item is picked up into the cart, the shopper is obliged eventually to return the cart to the north-west cart return.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "nw_cart_return_cell": "at(0,1)",
        "cart_parked_at_nw_return": "cartAt(0,1)"
      },
      "events": {
        "item_loaded_in_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "holding_cart"
            ]
          },
          "post": "holding_cart"
        },
        "return_cart_nw": {
          "pre": {
            "and": [
              "holding_cart",
              "nw_cart_return_cell",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_nw_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_loaded_in_cart",
      "discharge": "return_cart_nw"
    }
  }
]
